/* Generated by Trae Work */
/* 课表 v2：节次引擎 —— 每天上午/下午/晚上各 2 节（共 6 节）；
   课程合集 = 自考选科(2—4) + 考研科目(数二/英二/408)，优先科目固定每天第 1 节；
   合集与优先级保存后确定性重排（同参数必得同课表），用户覆盖（完成/跳过/拖拽）独立保存不受影响 */
"use strict";
(function () {
  const SLOT_NAMES = { morning: "上午", afternoon: "下午", evening: "晚上" };
  /* 每天节次：早 9:00–12:00、下午 13:00–17:30、晚上 18:30–22:00，每时段 2 节 */
  const PERIODS = [
    { slot: "morning",   label: "上午第1节", start: "09:00", end: "10:30", min: 90 },
    { slot: "morning",   label: "上午第2节", start: "10:30", end: "12:00", min: 90 },
    { slot: "afternoon", label: "下午第1节", start: "13:00", end: "15:15", min: 135 },
    { slot: "afternoon", label: "下午第2节", start: "15:15", end: "17:30", min: 135 },
    { slot: "evening",   label: "晚上第1节", start: "18:30", end: "20:15", min: 105 },
    { slot: "evening",   label: "晚上第2节", start: "20:15", end: "22:00", min: 105 }
  ];
  const SLOT_ORDER = ["morning", "afternoon", "evening"];
  const WEEKDAYS = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"];
  const SCHEDULE_START = "2026-11-03";
  const KAoyanTarget = SITE_DATA.countdown.kaoyan_target; // 2027-12-19

  /* ================= 基础工具 ================= */
  function mulberry(seed) {
    return function () {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function hashStr(s) { let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; } return h; }
  function mondayOf(date) {
    const d = new Date(date); d.setHours(0, 0, 0, 0);
    d.setDate(d.getDate() - (d.getDay() + 6) % 7);
    return d;
  }
  function weekIdxOf(weekStart) {
    return Math.round((weekStart - mondayOf(new Date(SCHEDULE_START + "T00:00:00"))) / (7 * 86400000));
  }
  function kaoyanStage() {
    const now = new Date(); const tgt = new Date(KAoyanTarget + "T00:00:00");
    const months = (tgt.getFullYear() - now.getFullYear()) * 12 + (tgt.getMonth() - now.getMonth());
    if (months > 6) return "basic";
    if (months > 3) return "enhance";
    return "sprint";
  }
  function nextZikaoWeeks() {
    try { const ev = nextZikaoDate(); return ev ? Math.max(0, Math.floor(daysUntil(ev.date_start) / 7)) : null; }
    catch (e) { return null; }
  }

  /* ================= 课程合集与优先级 ================= */
  const KY_ALL = ["数二", "英二", "408"];
  function zkSelectableCourses() {
    return SITE_DATA.zikao.courses.filter(c => c.chapters || c.reference_chapters);
  }
  function zkSelected() { return Store.get("zk_subjects", []); }
  function kySelected() { return Store.get("ky_subjects", KY_ALL.slice()); }
  function coursePool() { return zkSelected().concat(kySelected()); }
  function poolLabel(code) {
    if (code === "数二") return "数学（二）";
    if (code === "英二") return "英语（二）";
    if (code === "408") return "408 计算机学科专业基础综合";
    const c = SITE_DATA.zikao.courses.find(x => x.code === code);
    return c ? `${c.code} ${c.name}` : code;
  }
  function prioritySubject() {
    const p = Store.get("priority_subject", "");
    return coursePool().includes(p) ? p : "";
  }

  /* ================= 每日内容生成（确定性） ================= */
  function zkChapterOf(code, weekIdx, p) {
    const c = SITE_DATA.zikao.courses.find(x => x.code === code);
    const chapters = c.has_syllabus && c.chapters ? c.chapters : (c.reference_chapters ? c.reference_chapters.chapters : null);
    if (!c || !chapters || !chapters.length) return null;
    return { c, chapters, title: chapters[(weekIdx * 6 + p) % chapters.length] };
  }
  function blockFor(subjectCode, dateISO, weekKey, weekIdx, p, stage) {
    const rand = mulberry(hashStr(dateISO + subjectCode + p));
    let title, sb = "outline_section", url = "", subject = subjectCode;
    const weeks = nextZikaoWeeks();
    if (!["数二", "英二", "408"].includes(subjectCode)) {
      /* 自考科目 */
      const zc = zkChapterOf(subjectCode, weekIdx, p);
      if (!zc) return null;
      url = zc.c.has_syllabus ? zc.c.syllabus_url : zc.c.reference_chapters.source_url;
      sb = zc.c.has_syllabus ? "syllabus_chapter" : "reference_chapter";
      if (weeks !== null && weeks < 2) {
        title = `${zc.c.code} ${zc.c.name}：错题本回顾（考期临近，仅回顾已收录内容）`;
        sb = "past_paper";
      } else {
        title = `${zc.c.code} ${zc.c.name}：${zc.title}`;
      }
    } else if (subjectCode === "数二") {
      const SUBS = ["一元函数微分学", "一元函数积分学", "多元函数微积分（大纲范围内）", "常微分方程", "行列式与矩阵", "向量组与线性方程组", "特征值与二次型"];
      const t = SUBS[(weekIdx * 6 + p) % SUBS.length];
      title = stage === "sprint" ? `数学（二）：历年真题限时模拟 + ${t} 回顾` :
        stage === "enhance" ? `数学（二）：${t} + 整套题训练` : `数学（二）：${t}`;
    } else if (subjectCode === "英二") {
      const SUBS = ["完形填空（20 题 × 0.5 分）", "传统阅读 4 篇（20 题 × 2 分）", "新题型（5 题 × 2 分）", "翻译（约 150 词段落，15 分）", "写作（15 分）"];
      const t = SUBS[(weekIdx * 6 + p) % SUBS.length];
      title = stage === "sprint" ? `英语（二）：真题套卷 + 作文模板整理` : `英语（二）：${t}（单词 + 精读）`;
    } else {
      /* 408：四门子科轮转 */
      const subs = SITE_DATA.kaoyan.exam408.subjects;
      const sub = subs[(weekIdx * 6 + p) % subs.length];
      subject = sub.code;
      const ch = sub.chapters[(weekIdx * 6 + p) % sub.chapters.length];
      url = SITE_DATA.kaoyan.exam408.syllabus_source.source_url;
      if (stage === "sprint") {
        title = `408 · ${sub.name}：历年真题完整模拟与错题回顾（2009—2026）`;
        sb = "past_paper";
        url = SITE_DATA.kaoyan.papers.length ? SITE_DATA.kaoyan.papers[0].source_url : url;
      } else if (stage === "enhance") {
        title = `408 · ${sub.name}：${ch.title}（按板块刷真题：${ch.subs[0]} 等）`;
      } else {
        title = `408 · ${sub.name}：大纲章节「${ch.title}」`;
      }
    }
    const pd = PERIODS[p];
    return {
      id: `d-${dateISO}-p${p}`,
      date: dateISO, track: ["数二", "英二", "408"].includes(subjectCode) ? "kaoyan" : "zikao",
      subject, content_title: title, source_basis: sb,
      source_url: url || SITE_DATA.zikao.courses_source.source_url,
      duration_min: pd.min, time_slot: pd.slot, _p: p, status: "pending"
    };
  }

  function isBlankSlot(wd, slot) {
    const blank = Store.get("blank_half_day", { weekday: 5, slot: "afternoon" });
    return blank && blank.weekday === wd && blank.slot === slot;
  }
  function weekReduced(weekKey) {
    return Store.get("reduced_week_" + weekKey, false);
  }

  function generateDay(dateISO, weekKey, weekIdx) {
    if (dateISO < SCHEDULE_START) return [];
    const pool = coursePool();
    if (!pool.length) return [];
    const stage = kaoyanStage();
    const pri = prioritySubject();
    const offset = Math.abs(hashStr(weekKey)) % pool.length;
    const wd = (new Date(dateISO + "T00:00:00").getDay() + 6) % 7; // 0=Mon
    const isSunday = wd === 6;
    const reduced = weekReduced(weekKey);
    const blocks = [];
    for (let p = 0; p < 6; p++) {
      const pd = PERIODS[p];
      if (reduced && pd.slot === "evening") continue;           // 减负周：晚上不排
      if (isBlankSlot(wd, pd.slot)) continue;                    // 用户空白半日
      if (isSunday && pd.slot !== "evening") continue;           // 周日白天留白，仅晚上复盘
      const subj = (!isSunday && p === 0 && pri) ? pri : pool[(offset + p) % pool.length];
      let b = blockFor(subj, dateISO, weekKey, weekIdx, p, stage);
      if (!b) continue;
      if (isSunday) b.content_title = `本周复盘：${poolLabel(subj)} 错题与薄弱点回顾（弹性缓冲）`;
      blocks.push(b);
    }
    return blocks;
  }

  function generateWeek(weekStart) {
    const weekIdx = weekIdxOf(weekStart);
    const weekKey = fmtDate(weekStart);
    let blocks = [];
    for (let i = 0; i < 7; i++) {
      blocks = blocks.concat(generateDay(fmtDate(new Date(weekStart.getTime() + i * 86400000)), weekKey, weekIdx));
    }
    blocks = blocks.filter(b => b.date >= SCHEDULE_START);
    const ov = Store.get("block_overrides", {});
    const mv = Store.get("block_moves", {});
    blocks.forEach(b => {
      if (ov[b.id]) { b.status = ov[b.id].status; if (ov[b.id].reason) b.skip_reason = ov[b.id].reason; }
      if (mv[b.id] && mv[b.id].date) {
        const newDate = new Date(mv[b.id].date + "T00:00:00");
        if (newDate >= weekStart && newDate < new Date(weekStart.getTime() + 7 * 86400000)) {
          b.date = mv[b.id].date;
        }
      }
    });
    return blocks;
  }

  /* ================= 渲染 ================= */
  let currentDate = fmtDate(new Date());
  let weekMode = false;

  function render() {
    const view = document.getElementById("sch-view");
    const d = new Date(currentDate + "T00:00:00");
    const weekStart = mondayOf(d);
    const weekKey = fmtDate(weekStart);
    const blocks = generateWeek(weekStart).filter(b => weekMode || b.date === currentDate);
    const pool = coursePool();
    const pri = prioritySubject();
    const weeks = nextZikaoWeeks();
    const stage = kaoyanStage();

    let head = `<div class="sched-day-title">${weekMode
      ? `本周概览（${weekKey} 起）`
      : `${d.getMonth() + 1} 月 ${d.getDate()} 日 · ${WEEKDAYS[(d.getDay() + 6) % 7]} · 每时段 2 节`}</div>
      <p class="desc">上课节次：<strong>上午 9:00–12:00（2 节）· 下午 13:00–17:30（2 节）· 晚上 18:30–22:00（2 节）</strong><br>
      考研阶段：<strong>${stage === "basic" ? "基础期" : stage === "enhance" ? "强化期" : "冲刺期"}</strong>
      · 自考下次考期：<strong>${weeks === null ? "待官方公布" : `距考 ${weeks} 周`}</strong><br>
      课程合集：<strong>${pool.length ? pool.map(poolLabel).join("、") : "<strong>未选择</strong>"}</strong>
      · 优先科目：<strong>${pri ? poolLabel(pri) : "不优先（轮转）"}</strong></p>`;

    if (!pool.length) {
      head += `<div class="notice ref"><strong>请在下方「课程合集」中选择科目。</strong>未选择时课表为空。</div>`;
    }
    if (currentDate < SCHEDULE_START) {
      head += `<div class="notice info">排课起始日为 <strong>${SCHEDULE_START}</strong>，此前不生成课表块。</div>`;
    }

    let body = "";
    if (weekMode) {
      const cols = [...Array(7)].map((_, i) => {
        const day = new Date(weekStart.getTime() + i * 86400000);
        const iso = fmtDate(day);
        const dayBlocks = blocks.filter(b => b.date === iso).sort((a, b) => a._p - b._p);
        return `<div class="week-col${iso === currentDate ? " today" : ""}" data-date="${iso}">
          <h5>${WEEKDAYS[i]}<br><span style="font-weight:400">${iso.slice(5)}</span></h5>
          ${dayBlocks.map(b => miniBlockHtml(b)).join("") || `<div style="font-size:11.5px;color:var(--muted);text-align:center;">—</div>`}
        </div>`;
      }).join("");
      body = `<div class="week-grid">${cols}</div><p class="desc" style="margin-top:10px;">支持同周内拖拽调整；用户覆盖存 localStorage，引擎重排不影响完成/跳过状态。</p>`;
    } else {
      body = SLOT_ORDER.map(slot => {
        const bs = blocks.filter(b => b.time_slot === slot).sort((a, b) => a._p - b._p);
        return `<div class="slot-group"><h4>${SLOT_NAMES[slot]}</h4>${
          bs.length ? bs.map(b => blockHtml(b)).join("") : `<div class="notice empty">${isBlankSlot((d.getDay() + 6) % 7, slot) ? "你设置的空白半日，引擎不在该时段排课。" : "该时段暂无课表块。"}</div>`
        }</div>`;
      }).join("");
    }

    view.innerHTML = head + body;
    bindBlockActions(view);
    if (weekMode) bindDnD(view);
    renderSkipNudge();
    renderSettings();
  }

  function blockHtml(b) {
    const pd = PERIODS[b._p];
    return `<div class="block ${b.track} ${b.status}" draggable="true" data-id="${b.id}" data-date="${b.date}">
      <div>
        <div class="b-title">${badge(b.track)} ${pd.label}：${b.content_title}</div>
        <div class="b-meta"><strong>${pd.start}–${pd.end}</strong> · ${subjectName(b.subject)} · ${b.duration_min} 分钟 · ${b.status === "done" ? "已完成" : b.status === "skipped" ? `已跳过${b.skip_reason ? "（" + b.skip_reason + "）" : ""}` : "待完成"}</div>
        <div class="b-src src">source_basis：${b.source_basis} · 来源：<a href="${b.source_url}" target="_blank" rel="noopener">${b.source_url}</a></div>
      </div>
      <div class="block-actions">
        ${b.status !== "done" ? `<button data-act="done" data-id="${b.id}">完成</button>` : ""}
        ${b.status !== "skipped" ? `<button data-act="skip" data-id="${b.id}">跳过</button>` : `<button data-act="reset" data-id="${b.id}">撤销</button>`}
      </div>
    </div>`;
  }
  function miniBlockHtml(b) {
    const pd = PERIODS[b._p];
    return `<div class="mini-block ${b.track} ${b.status}" draggable="true" data-id="${b.id}" data-date="${b.date}" title="${pd.start}–${pd.end} ${b.content_title}">
      <div class="mb-t">${pd.label} ${pd.start} ${subjectName(b.subject)}</div>
      <div class="b-meta">${pd.start}–${pd.end} · ${b.status === "done" ? "✓" : b.status === "skipped" ? "跳过" : ""}</div>
    </div>`;
  }

  function bindBlockActions(root) {
    root.querySelectorAll("button[data-act]").forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.id, act = btn.dataset.act;
        const ov = Store.get("block_overrides", {});
        if (act === "done") ov[id] = { status: "done" };
        else if (act === "skip") {
          const reason = prompt("跳过原因（可选，直接确定留空）：") || "";
          ov[id] = { status: "skipped", reason };
        } else if (act === "reset") delete ov[id];
        Store.set("block_overrides", ov);
        render();
      });
    });
  }
  function bindDnD(root) {
    let dragId = null;
    root.querySelectorAll("[draggable=true]").forEach(el => {
      el.addEventListener("dragstart", e => { dragId = el.dataset.id; });
      el.addEventListener("dragend", () => { dragId = null; root.querySelectorAll(".week-col").forEach(c => c.classList.remove("drag-over")); });
    });
    root.querySelectorAll(".week-col").forEach(col => {
      col.addEventListener("dragover", e => { e.preventDefault(); col.classList.add("drag-over"); });
      col.addEventListener("dragleave", () => col.classList.remove("drag-over"));
      col.addEventListener("drop", e => {
        e.preventDefault(); col.classList.remove("drag-over");
        if (!dragId) return;
        if (col.dataset.date < SCHEDULE_START) { alert(`排课起始日为 ${SCHEDULE_START}，不能移动到该日期之前。`); return; }
        const mv = Store.get("block_moves", {});
        mv[dragId] = { date: col.dataset.date };
        Store.set("block_moves", mv);
        render();
      });
    });
  }

  /* ================= 连续 3 天跳过提示 ================= */
  function renderSkipNudge() {
    const box = document.getElementById("skip-nudge-box");
    const nudge = document.getElementById("skip-nudge");
    const ov = Store.get("block_overrides", {});
    const days = [...Array(3)].map((_, i) => { const d = new Date(); d.setDate(d.getDate() - i); return fmtDate(d); });
    const skipped3 = days.every(day => Object.keys(ov).some(id => ov[id].status === "skipped" && id.includes(day)));
    const ack = Store.get("skip_nudge_ack_" + days[0], false);
    if (skipped3 && !ack) {
      box.style.display = "";
      nudge.innerHTML = `连续 3 天有块被跳过。<strong>是否需要减少下周排课量？</strong>
        <button class="btn small" id="nudge-yes">是，下周晚上不排课（每天 4 节）</button>
        <button class="btn small ghost" id="nudge-no">否，保持当前节奏</button>`;
      document.getElementById("nudge-yes").addEventListener("click", () => {
        Store.set("reduced_week_" + fmtDate(new Date(mondayOf(new Date()).getTime() + 7 * 86400000)), true);
        Store.set("skip_nudge_ack_" + days[0], true);
        render();
      });
      document.getElementById("nudge-no").addEventListener("click", () => {
        Store.set("skip_nudge_ack_" + days[0], true);
        render();
      });
    } else box.style.display = "none";
  }

  /* ================= 设置面板：课程合集 + 优先科目 ================= */
  function renderSettings() {
    const list = document.getElementById("zk-subject-list");
    const sel = zkSelected();
    if (!list.dataset.built) {
      list.innerHTML = zkSelectableCourses().map(c =>
        `<label><input type="checkbox" value="${c.code}" ${sel.includes(c.code) ? "checked" : ""}> ${c.code} ${c.name}（${c.has_syllabus ? "官方大纲" : "参考章节"}）</label>`).join("");
      list.addEventListener("change", () => {
        const checked = [...list.querySelectorAll("input:checked")].map(i => i.value);
        if (checked.length > 4) {
          alert("黑龙江自考每次最多报考 4 门。");
          list.querySelector(`input[value="${checked[checked.length - 1]}"]`).checked = false;
        }
      });
      list.dataset.built = "1";
    }
    document.getElementById("zk-subject-save").onclick = () => {
      const checked = [...list.querySelectorAll("input:checked")].map(i => i.value);
      if (checked.length > 0 && checked.length < 2) { alert("自考科目至少选择 2 门（每次最多 4 门）"); return; }
      Store.set("zk_subjects", checked);
      render();
    };

    /* 考研科目合集 */
    const kyList = document.getElementById("ky-subject-list");
    const ky = kySelected();
    if (!kyList.dataset.built) {
      kyList.innerHTML = [
        ["数二", "数学（二）（150 分）"],
        ["英二", "英语（二）（100 分）"],
        ["408", "408 计算机学科专业基础综合（150 分，含四门子科轮转）"]
      ].map(([v, label]) => `<label><input type="checkbox" value="${v}" ${ky.includes(v) ? "checked" : ""}> ${label}</label>`).join("");
      kyList.dataset.built = "1";
    }
    document.getElementById("ky-subject-save").onclick = () => {
      const checked = [...kyList.querySelectorAll("input:checked")].map(i => i.value);
      if (!checked.length) { alert("考研科目至少保留 1 门；如完全不备考研请全部取消并同时清空自考科目。"); return; }
      Store.set("ky_subjects", checked);
      if (!checked.includes(Store.get("priority_subject", ""))) Store.set("priority_subject", "");
      render();
    };

    /* 优先科目 */
    const psel = document.getElementById("priority-select");
    const pool = coursePool();
    const cur = prioritySubject();
    psel.innerHTML = `<option value="">不优先（按周轮转）</option>` +
      pool.map(c => `<option value="${c}" ${c === cur ? "selected" : ""}>${poolLabel(c)}</option>`).join("");
    document.getElementById("priority-save").onclick = () => {
      Store.set("priority_subject", psel.value);
      render();
    };

    /* 空白半日 */
    const bw = document.getElementById("blank-weekday");
    if (!bw.dataset.built) {
      bw.innerHTML = WEEKDAYS.map((w, i) => `<option value="${i}">${w}</option>`).join("");
      bw.dataset.built = "1";
    }
    const blank = Store.get("blank_half_day", { weekday: 5, slot: "afternoon" });
    bw.value = blank.weekday;
    document.getElementById("blank-slot").value = blank.slot;
    document.getElementById("blank-save").onclick = () => {
      Store.set("blank_half_day", { weekday: +bw.value, slot: document.getElementById("blank-slot").value });
      render();
    };
    document.getElementById("sch-reset").onclick = () => {
      if (!confirm("清空所有课表本地记录（选科/合集/优先级保留）？")) return;
      ["block_overrides", "block_moves"].forEach(k => Store.del(k));
      Object.keys(localStorage).filter(k => k.startsWith("heuprep:reduced_") || k.startsWith("heuprep:skip_nudge_ack_")).forEach(k => localStorage.removeItem(k));
      render();
    };
  }

  /* ================= 事件 ================= */
  document.addEventListener("DOMContentLoaded", () => {
    document.getElementById("sch-prev").addEventListener("click", () => { const d = new Date(currentDate + "T00:00:00"); d.setDate(d.getDate() - 1); currentDate = fmtDate(d); render(); });
    document.getElementById("sch-next").addEventListener("click", () => { const d = new Date(currentDate + "T00:00:00"); d.setDate(d.getDate() + 1); currentDate = fmtDate(d); render(); });
    document.getElementById("sch-today").addEventListener("click", () => { currentDate = fmtDate(new Date()); render(); });
    document.getElementById("sch-week-toggle").addEventListener("click", e => {
      weekMode = !weekMode;
      e.target.textContent = weekMode ? "切回单日视图" : "切换本周概览";
      render();
    });
    render();
  });
})();
